        return EXIT_FAILURE;
    }

    Paddle paddle(375, 550, 100, 20);
    std::vector<Ball> balls;
    for (int i = 0; i < 5; ++i) {
        balls.emplace_back(400, 300, 10);
    }

    Score score(10, 10, 20, font);
