    sf::Time timeSinceLastFrame = sf::Time::Zero;

    while (window.isOpen()) {
        sf::Event event;
        while (window.pollEvent(event)) {
            if (event.type == sf::Event::Closed)
                window.close();
        }

        // Handle input
        if (sf::Keyboard::isKeyPressed(sf::Keyboard::Left)) {
            paddle.move(-paddle.speed);
        }
        if (sf::Keyboard::isKeyPressed(sf::Keyboard::Right)) {
            paddle.move(paddle.speed);
        }

        // Update game objects
        timeSinceLastFrame = clock.restart();
        float deltaTime = timeSinceLastFrame.asSeconds();

        // Check if any ball is out of bounds
        bool anyBallOut = false;
        for (auto &ball : balls) {
            if (ball.isOutofBounds(window)) {
                anyBallOut = true;
                break;
            }
        }

        if (anyBallOut) {
            // Remove the ball that is out of bounds
            for (auto it = balls.begin(); it != balls.end(); ++it) {
                if (it->isOutOfBounds(window)) {
                    balls.erase(it);
                    break;
                }
            }
        }

        // If no balls are left, reset the game
        if (balls.empty()) {
            // Reset the game
            balls.clear();
            balls.emplace_back(400, 300, 10);
        }

        // Update balls
        for (auto &ball : balls) {
            ball.update();
        }

        // Check for collisions with paddle
        for (auto &ball : balls) {
            if (ball.getBounds().intersects(paddle.getBounds())) {
                ball.reverseVelocityY();
            }
        }

        // Check for collisions with bricks
        std::vector<Brick> bricks;
        for (int row = 0; row < 5; ++row) {
            for (int col = 0; col < 10; ++col) {
                float x = 75 + col * 70;
                float y = 50 + row * 40;
                bricks.emplace_back(x, y, 60, 20, sf::Color::Red);
            }
        }

        for (auto &ball : balls) {
            for (auto &brick : bricks) {
                if (ball.getBounds().intersects(brick.getBounds())) {
                    ball.reverseVelocityY();
                    brick.setDestroyed(true);
                    score.update(10);
                    break;
                }
            }
        }

        // Draw everything
        window.clear();
        paddle.draw(window);
        for (auto &ball : balls) {
            ball.draw(window);
        }
        for (auto &brick : bricks) {
            brick.draw(window);
        }
        score.draw(window);
        window.display();
    }

    return 0;
}
