bool isAnagram(string str1, string str2) {
    // Step 1: Check if lengths are equal
    if (str1.length() != str2.length()) {
        return false;
    }

    // Step 2: Convert both strings to lowercase
    for (char &c : str1) {
        c = tolower(c);
