let purple = "#9B59B6";
let blue = "#2980B9";
let yellow = "#F1C40F";
let green = "#27AE60";
let colors = [pink, purple, blue, yellow, green];

function setup() {
  createCanvas(800, 800);
  noStroke();
}

function draw() {
  background(255, 10); // Slight transparency for fading effect
  let gridSize = 20;
  let cellSize = width / gridSize;

  for (let i = 0; i < gridSize; i++) {
    for (let j = 0; j < gridSize; j++) {
      let x = i * cellSize;
      let y = j * cellSize;

      // Vary cell size with Perlin noise
      let noiseValue = noise(i * 0.05 + frameCount * 0.01, j * 0.05 + frameCount * 0.01);
      let size = map(noiseValue, 0, 1, cellSize * 0.5, cellSize * 1.5);
      let offset = random(-size/2, size/2);

      // Random color with transparency
      let c = random(colors);
      let alpha = random(100, 255);
      fill(c, alpha);

      // Create abstract shapes with gradients
      if (random() < 0.3) {
        // Radial gradient ellipse
        let gradient = createRadialGradient(0, 0, 0, 0, size/2);
        fill(gradient);
        ellipse(x + cellSize/2, y + cellSize/2, size);
      } else if (random() < 0.6) {
        // Random polygon
        let sides = floor(random(3, 6));
        let angle = TWO_PI / sides;
        let radius = size / 2;
        let xCenter = x + cellSize/2 + offset;
        let yCenter = y + cellSize/2 + offset;
        beginShape();
        for (let a = 0; a < TWO_PI; a += angle) {
          let sx = xCenter + cos(a) * radius;
          let sy = yCenter + sin(a) * radius;
          vertex(sx, sy);
        }
        endShape(CLOSE);
      } else {
        // Triangle with noise-based position
        let x1 = x + offset + noise(i * 0.02, j * 0.02) * size/2;
        let y1 = y + offset + noise(i * 0.02 + 100, j * 0.02 + 100) * size/2;
        let x2 = x + size + offset + noise(i * 0.02 + 200, j * 0.02 + 200) * size/2;
        let y2 = y + size + offset + noise(i * 0.02 + 300, j * 0.02 + 300) * size/2;
        triangle(x1, y1, x2, y1, x1, y2);
      }

      // Add lines to break grid with varying styles
      if (random() < 0.3) {
        let lineWidth = random(1, 3);
        let lineColor = color(random(100, 255), random(100, 255), random(100, 255), random(100, 255));
        stroke(lineColor);
        strokeWeight(lineWidth);
        line(x, y, x + cellSize, y + cellSize);
      }
    }
  }
}

// Function to create radial gradient
function createRadialGradient(x, y, r1, r2, alpha) {
  let gradient = createGraphics(width, height);
  gradient.noStroke();
  gradient.fill(255, alpha);
  gradient.ellipse(x, y, r1, r1);
  gradient.fill(0, alpha);
  gradient.ellipse(x, y, r2, r2);
  return gradient;
}
